INSERT INTO NOTIFICATION
    (NOTIFICATION_ID, MEMBER_ID, ADMIN_ID, NOTIF_TYPE, TITLE, BODY, LINK_PAGE, REF_ID)
SELECT SEQ_NOTIFICATION.NEXTVAL, gm.MEMBER_ID, NULL,
       #{row.notifType}, #{row.title}, #{row.body},
       #{row.linkPage, jdbcType=VARCHAR}, #{row.refId, jdbcType=NUMERIC}
  FROM GYE_MEMBER gm
 WHERE gm.GROUP_ID = #{groupId}
   AND gm.STATUS = 'ACTIVE'

   AND gm.MEMBER_ID NOT IN
    #{id}
